char resolve_char(char *S,long long k){
    long long n=strlen(S);
    long long L=n;
    while(L<k) L*=2;
    int flip=0;
    while(L>n){
        long long half=L/2;
        if(k>half){ k-=half; flip^=1; }
        L=half;
    }
    char c=S[k-1];
    if(flip){
        if(c>='a' && c<='z') c = c-'a'+'A';
        else if(c>='A' && c<='Z') c = c-'A'+'a';
    }
    return c;
}

